<?php
use SwimlogStandalone\WorkoutLog as WL; use SwimlogStandalone\CalendarView as CV; use SwimLogEvaluation\Workout;
$values=is_wp_error($log)?WL::defaults():$log['filters'];
if(is_wp_error($log)) foreach(array('from','to','type') as $key) if(isset($_GET[$key])&&is_string($_GET[$key]))$values[$key]=$_GET[$key];
$types=is_wp_error($log)?array('all'=>'All activities','pool'=>'Pool swimming','open_water'=>'Open-water swimming'):$log['types'];
if(is_wp_error($log)&&class_exists('SwimLogEvaluation\\Land_Activity')&&\SwimLogEvaluation\Land_Activity::authorized($owner)) $types+=array('running'=>'Running','walking'=>'Walking');
?>
<section class="calendar-panel log-panel" aria-labelledby="log-title"><div class="log-heading"><p class="eyebrow">RECORDED HISTORY</p><h2 id="log-title">Workout Log</h2><p>Find a session, review its details, and keep each activity in perspective.</p></div>
<form method="get" class="log-filters"><input type="hidden" name="screen" value="log"><div><label for="log-from">From</label><input id="log-from" name="from" type="date" min="1900-01-01" max="2199-12-31" value="<?php echo esc_attr($values['from']); ?>"></div><div><label for="log-to">To</label><input id="log-to" name="to" type="date" min="1900-01-01" max="2199-12-31" value="<?php echo esc_attr($values['to']); ?>"></div><div><label for="log-type">Activity</label><select id="log-type" name="type"><?php foreach($types as $type=>$label): ?><option value="<?php echo esc_attr($type); ?>" <?php selected($values['type'],$type); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></div><button>Apply filters</button><a class="control" href="/?screen=log">Reset</a><a class="control" href="/?screen=log&amp;from=&amp;to=&amp;type=all">All history</a></form>
<?php if(is_wp_error($log)): ?><p class="log-message" role="alert"><?php echo esc_html($log->get_error_message()); ?></p><?php else: ?>
<?php if($log['totals']!==null): ?><div class="log-totals"><?php foreach($log['totals'] as $label=>$total): ?><section><h3><?php echo esc_html($label); ?></h3><p class="log-total-distance"><?php echo esc_html($total['count']>0&&$total['known']===0?'Distance unavailable':number_format_i18n((float)$total['distance'],floor((float)$total['distance'])==(float)$total['distance']?0:2).' m'); ?></p><p><?php echo esc_html(number_format_i18n($total['count'])); ?> workouts<?php if($total['known']<$total['count']): ?><br><span><?php echo esc_html($total['count']-$total['known']); ?> without recorded distance</span><?php endif; ?></p></section><?php endforeach; ?></div><p class="log-caption">Totals cover all matching workouts across every page. Total distances are shown in meters; individual workouts retain their recorded units.</p><?php else: ?><p class="log-message">History is available below. Narrow the date range to calculate totals when more than <?php echo esc_html(number_format_i18n(WL::SUMMARY_LIMIT)); ?> workouts match.</p><?php endif; ?>
<p class="log-count" role="status"><?php echo esc_html(number_format_i18n($log['total'])); ?> matching workouts · Page <?php echo esc_html($log['page']); ?> of <?php echo esc_html($log['pages']); ?></p>
<?php if(!$log['rows']): ?><div class="log-empty"><h3>No workouts match these filters</h3><p>Try a wider date range or a different activity type.</p></div><?php else: ?>
<div class="log-table-wrap"><table class="workout-log-table"><caption class="sr-only">Recorded workouts, newest first</caption><thead><tr><th scope="col">Date and time</th><th scope="col">Activity</th><th scope="col">Distance</th><th scope="col">Elapsed time</th><th scope="col">Location</th><th scope="col">Details</th></tr></thead><tbody>
<?php foreach($log['rows'] as $workout): ?><tr data-log-row="<?php echo esc_attr($workout->id); ?>"><td data-label="Date and time"><time datetime="<?php echo esc_attr(str_replace(' ','T',$workout->workout_start)); ?>"><?php echo esc_html($workout->workout_start); ?></time></td><td data-label="Activity"><?php echo esc_html(WL::label($workout->workout_type)); ?></td><td data-label="Distance"><?php echo esc_html(isset($workout->original_distance)&&!empty($workout->original_distance_unit)?CV::distance($workout->original_distance,$workout->original_distance_unit):CV::distance($workout->total_distance_m)); ?></td><td data-label="Elapsed time"><?php echo esc_html(Workout::format_duration($workout->elapsed_time_ms)); ?></td><td data-label="Location"><?php echo esc_html($workout->location_name??'—'); ?></td><td data-label="Details"><a class="workout-trigger log-detail-link" data-workout-id="<?php echo esc_attr($workout->id); ?>" aria-haspopup="dialog" aria-expanded="false" href="<?php echo esc_url(WL::url($log['filters'],$log['page']).'&workout='.$workout->id); ?>">View details<span class="sr-only"> for <?php echo esc_html(WL::label($workout->workout_type).' '.$workout->workout_start); ?></span></a></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?>
<nav class="log-pagination" aria-label="Workout log pages"><?php if($log['page']>1): ?><a class="control" rel="prev" href="<?php echo esc_url(WL::url($log['filters'],$log['page']-1)); ?>">← Previous page</a><?php endif; ?><span>Page <?php echo esc_html($log['page']); ?> of <?php echo esc_html($log['pages']); ?></span><?php if($log['page']<$log['pages']): ?><a class="control" rel="next" href="<?php echo esc_url(WL::url($log['filters'],$log['page']+1)); ?>">Next page →</a><?php endif; ?></nav>
<?php endif; ?></section>
